package com.dukankhata.closing; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface DailyClosingRepository extends JpaRepository<DailyClosing,UUID>{Optional<DailyClosing> findByIdAndShopId(UUID id,UUID shopId);Optional<DailyClosing> findByShopIdAndBusinessDate(UUID shopId,LocalDate businessDate);List<DailyClosing> findTop30ByShopIdOrderByBusinessDateDesc(UUID shopId);
@Query("select coalesce(sum(case when c.posSaleCount is null or c.posSaleCount=0 then c.expectedSales else 0 end),0), coalesce(sum(c.expensesTotal),0) from DailyClosing c where c.shop.id=:shopId and c.businessDate between :from and :to and c.status=:status") List<Object[]> summarizeByShopAndDateRange(@Param("shopId") UUID shopId,@Param("from") LocalDate from,@Param("to") LocalDate to,@Param("status") ClosingStatus status);
List<DailyClosing> findByShopIdAndBusinessDateBetweenAndStatusOrderByBusinessDateAsc(UUID shopId, LocalDate from, LocalDate to, ClosingStatus status);}
